INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT137-S4-Q7$batch10$, 137, 4, 7, $batch10$Principle-Strengthen$batch10$, $batch10$Even though MacArthur's diet book helped many people lose weight, MacArthur should not have published it. It recommended such small portions of fruits and vegetables that it undoubtedly damaged the health of many who followed the diet. MacArthur is a physician, so MacArthur either knew or should have known that diets low in fruits and vegetables are unhealthful.$batch10$, $batch10$Which one of the following principles, if valid, most helps to justify the argument's reasoning?$batch10$, $batch10$E$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=137 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT137-S4-Q7$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$One should not undertake an action if one knows that doing so would seriously damage the health of many people.$batch10$, $batch10$Too Narrow$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT137-S4-Q7$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$One should not follow a particular method for achieving some end if doing so has the potential to damage one's health.$batch10$, $batch10$Wrong Target$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT137-S4-Q7$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$One should publish a book recommending certain health-related measures if doing so is likely to improve many people's lives without also causing harm.$batch10$, $batch10$Opposite Direction$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT137-S4-Q7$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$One should not publish a book recommending a particular means of attaining a goal unless one knows that the particular means can bring about that goal.$batch10$, $batch10$Doesn't Apply$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT137-S4-Q7$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$One should not publish a book recommending a particular course of action if one either knows or ought to know that taking that course of action would be unhealthful.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT137-S4-Q7$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT137-S4-Q7$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$MacArthur should not have published the diet book.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$The book recommended so few fruits and vegetables that it damaged many followers' health. As a physician, MacArthur knew or should have known that such diets are unhealthful.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The evidence gives two facts: publishing recommended an unhealthful course, and MacArthur knew or should have known it. The principle must turn those two facts into "should not have published."$batch10$), (3, $batch10$Goal$batch10$, $batch10$One should not publish a book recommending a course of action that one knows, or should know, is unhealthful.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT137-S4-Q7$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This needs MacArthur to know the book would seriously damage health. The argument says only that MacArthur knew or should have known. If MacArthur merely should have known, the principle doesn't apply.$batch10$), ($batch10$B$batch10$, $batch10$This tells people not to follow a harmful method. The conclusion is about whether MacArthur should have published, not what readers should do.$batch10$), ($batch10$C$batch10$, $batch10$This says when one should publish. The argument concludes that MacArthur shouldn't have, and this principle can't get there.$batch10$), ($batch10$D$batch10$, $batch10$This is about knowing the means will reach the goal. The book did help people lose weight, so the problem isn't that it failed. The problem is the harm to health.$batch10$), ($batch10$E$batch10$, $batch10$MacArthur published a book recommending a diet that was unhealthful, and either knew or ought to have known it. This principle says not to publish in that situation, so MacArthur shouldn't have.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT137-S4-Q7$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
